package site.cadera.arunika.dungeon.battle;
import java.util.*;
import static site.cadera.arunika.dungeon.battle.BattlePlan.*;
import static site.cadera.arunika.dungeon.battle.ArenaAccessPolicy.*;
public final class GatewayTest {
 static int n;static Point p(double x){return new Point("world",x,65,0);}static void check(boolean ok,String text){if(!ok)throw new AssertionError(text);n++;System.out.println("PASS "+text);}
 public static void main(String[] args){Bounds a=new Bounds(new Point("world",0,60,-5),new Point("world",10,70,5)),b=new Bounds(new Point("world",20,60,-5),new Point("world",30,70,5));
 check(permitted(p(100),false,List.of()),"survival outside arenas unaffected");check(!permitted(p(5),true,List.of()),"idle arena entry denied");check(!permitted(p(5),true,List.of(new Active(a,false))),"nonparticipant denied active arena");check(permitted(p(5),true,List.of(new Active(a,true),new Active(b,false))),"living member can move within own arena");check(!permitted(p(25),true,List.of(new Active(a,true),new Active(b,false))),"cross arena entry denied");check(!permitted(p(100),false,List.of(new Active(a,true))),"unauthorized exit denied");check(permitted(p(100),false,List.of(new Active(a,false))),"eliminated participant may leave");check(!permitted(p(5),true,List.of(new Active(a,false))),"eliminated participant may not reenter");check(permitMatches(p(5),p(5)),"exact destination permit");check(!permitMatches(p(5),p(6)),"redirected destination permit denied");check(!permitMatches(null,p(5)),"missing permit denied");check(!permitMatches(p(5),new Point("other",5,65,0)),"cross-world permit denied");check(returnMatches("queen/a","queen","a",a,p(5),p(6),true),"return from own arena");check(!returnMatches("queen/b","queen","a",a,p(5),p(6),true),"wrong arena return denied");check(!returnMatches("queen/a","queen","a",a,p(25),p(6),true),"return stone outside arena denied");check(!returnMatches("queen/a","queen","a",a,p(5),p(25),true),"player outside arena denied");check(!returnMatches("queen/a","queen","a",a,p(5),p(6),false),"eliminated player cannot return through active battle gate");check(near(p(0),p(6),6),"hub radius boundary accepted");check(!near(p(0),p(6.1),6),"hub radius enforced");check(!near(p(0),new Point("other",0,65,0),6),"hub world must match");check(!near(null,p(0),6),"missing anchor denied");check(!near(p(0),p(0),Double.NaN),"invalid radius denied");check(!near(p(0),p(0),-1),"negative radius denied");System.out.println("TOTAL "+n+" PASS");}
}
